import pandas as pd
import numpy as np

data1 = {
    'score': [1, 2],
    'seconds': [1140, 2100],
}

data2 = {
    'prize': [5.5, 14.5, 14.6, 21, 23, 24, 26, 38, 39, 40, 50],
    'seconds': [840, 1080, 1380, 1620, 1650, 1680, 1700, 1740, 2040, 2100, 2160],
}

df1 = pd.DataFrame.from_dict(data1)
df2 = pd.DataFrame.from_dict(data2)

result = []

for sec in df1['seconds']:
    idx = np.searchsorted(df2['seconds'], sec)

    if idx == 0:
        result.append(df2.iloc[0:3])  # Take 3 rows from the top
    elif idx == len(df2):
        result.append(df2.iloc[-3:])  # Take 3 rows from the bottom
    else:
        result.append(df2.iloc[idx-1:idx+2])  # Take the closest match and 2 rows above and below

result_df = pd.concat(result).drop_duplicates().reset_index(drop=True)
print(result_df)

