        self.left = None
        self.right = None

    def add_child(self, val):
        if self.value:
            if val < self.value:
                if self.left is None:
                    self.left = BST(val)
                else:
                    self.left.add_child(val)
            else:
                if val > self.value:
                    if self.right is None:
                        self.right = BST(val)
                    else:
                        self.right.add_child(val)
        else:
            self.value = val

    def traverse_pre(self, result=None):
        if result is None:
            result = []
        result.append(self.value)

        if self.left:
            self.left.traverse_pre(result)

        if self.right:
            self.right.traverse_pre(result)

        return result


