import pandas as pd
from typing import List, Type
from pydantic import BaseModel, root_validator

def root_unique_validator(*fields: str):
    def validator(cls, values):
        root_values = values.get("__root__", [])
        seen = {field: set() for field in fields}

        for value in root_values:
            for field in fields:
                if value[field] in seen[field]:
                    raise ValueError(f"Duplicate value found in column: {field}")
                seen[field].add(value[field])

        return values
    return root_validator(pre=True)(validator)

class CustomerRecord(BaseModel):
    id: int
    name: str
    address: str

class CustomerRecordDF(BaseModel):
    __root__: List[CustomerRecord]

    _validate_unique = root_unique_validator("name", "address")

df = pd.DataFrame({'id': [1, 2, 3], 
                   'name': ['Bob', 'Joe', 'Bob'], 
                   'address': ['123 Fake St', '125 Fake St', '123 Fake St']})

df_dict = df.to_dict(orient='records')

try:
    CustomerRecordDF.parse_obj(df_dict)
except ValueError as e:
    print(e)

import polars as pl
from datetime import datetime
import pytz

df = pl.DataFrame({
    "time": [datetime(2023, 4, 3, 2), datetime(2023, 4, 4, 3), datetime(2023, 4, 5, 4)],
    "tzone": ["Asia/Tokyo", "America/Chicago", "Europe/Paris"]
}).with_columns(pl.col("time").dt.replace_time_zone("UTC"))

def convert_timezone(time, timezone):
    return time.replace(tzinfo=pytz.utc).astimezone(pytz.timezone(timezone)).hour

df = df.with_columns(
    pl.struct(["time", "tzone"]).map_elements(lambda x: convert_timezone(x["time"], x["tzone"])).alias("hour")
)

print(df)

