["from fastapi import FastAPI, Request
from starlette.middleware.base import BaseHTTPMiddleware
from starlette.responses import Response
import json

app = FastAPI()

class MetadataMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        response = await call_next(request)
        if response.headers.get("content-type") != "application/json":
            return response

        body = b"".join([chunk async for chunk in response.body_iterator])

        try:
            original_data = json.loads(body.decode())
        except json.JSONDecodeError:
            return response  # Return original response if not valid JSON

        data = {
            "data": original_data,
            "metadata": {
                "some_data_key_1": "some_data_value_1",
                "some_data_key_2": "some_data_value_2",
                "some_data_key_3": "some_data_value_3"
            }
        }

        body = json.dumps(data).encode("utf-8")

        return Response(
            content=body,
            status_code=response.status_code,
            media_type="application/json"
        )

app.add_middleware(MetadataMiddleware)

@app.get("/test")
async def test_endpoint():
    return {"message": "Hello, world!"}

# Test Case
from fastapi.testclient import TestClient

client = TestClient(app)

def test_metadata_middleware():
    response = client.get("/test")
    assert response.status_code == 200
    assert "metadata" in response.json()
    assert response.json()["data"] == {"message": "Hello, world!"}

test_metadata_middleware()
"]

